import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String start = in.next(), target = in.next();
        // BFS over valid strings; each edge recolors one position
        HashMap<String, Integer> dist = new HashMap<>();
        dist.put(start, 0);
        ArrayDeque<String> q = new ArrayDeque<>();
        q.add(start);
        while (!q.isEmpty()) {
            String s = q.poll();
            int d = dist.get(s);
            if (s.equals(target)) { System.out.println(d); return; }
            char[] arr = s.toCharArray();
            for (int i = 0; i < n; i++)
                for (char c : new char[]{'x', 'y', 'z'}) {
                    if (c == arr[i] || (i > 0 && arr[i - 1] == c) || (i + 1 < n && arr[i + 1] == c)) continue;
                    char old = arr[i];
                    arr[i] = c;
                    String t = new String(arr);
                    arr[i] = old;
                    if (!dist.containsKey(t)) { dist.put(t, d + 1); q.add(t); }
                }
        }
        System.out.println(-1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	var n int
	var start, target string
	fmt.Fscan(r, &n, &start, &target)
	// BFS over valid strings; each edge recolors one position
	dist := map[string]int{start: 0}
	q := []string{start}
	for head := 0; head < len(q); head++ {
		s := q[head]
		d := dist[s]
		if s == target {
			fmt.Println(d)
			return
		}
		for i := 0; i < n; i++ {
			for _, c := range []byte("xyz") {
				if c == s[i] || (i > 0 && s[i-1] == c) || (i+1 < n && s[i+1] == c) {
					continue
				}
				t := []byte(s)
				t[i] = c
				ts := string(t)
				if _, ok := dist[ts]; !ok {
					dist[ts] = d + 1
					q = append(q, ts)
				}
			}
		}
	}
	fmt.Println(-1)
}
